package top.rongshangs.watchface;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.text.InputFilter;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public final class MainActivity extends Activity {
 static final int PICK_PHOTO=10,SAVE_BIN=11,SAVE_PREVIEW=12;
 static final int BG=0xff101714,CARD=0xff1c2722,FG=0xffeef3ed,MUTED=0xffa3b4aa,ACCENT=0xffa5d7c4;
 WatchfaceEngine engine;WatchPreview preview;SeekBar zoom;Button exportButton,chooseButton;TextView colorLabel,status;LinearLayout imageColors;
 SharedPreferences prefs;final ExecutorService worker=Executors.newSingleThreadExecutor();boolean busy;String faceName="若叶睦";
 File photoFile(){return new File(getFilesDir(),"photo.png");}File pendingFile(){return new File(getFilesDir(),"pending.bin");}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("studio",MODE_PRIVATE);faceName=prefs.getString("name","若叶睦");try{engine=new WatchfaceEngine(this);}catch(Exception e){new AlertDialog.Builder(this).setMessage("模板未能加载，请重新安装应用。").setPositiveButton("关闭",(d,w)->finish()).setCancelable(false).show();return;}build();restore();}
 GradientDrawable shape(int color,int radius){GradientDrawable s=new GradientDrawable();s.setColor(color);s.setCornerRadius(dp(radius));return s;}
 TextView text(String value,int size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setFontFeatureSettings("kern");return v;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 Button button(String title,boolean primary){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(primary?BG:FG);b.setBackground(shape(primary?ACCENT:0xff2a3931,16));b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setStateListAnimator(null);return b;}
 void gap(LinearLayout p,int h){p.addView(new View(this),new LinearLayout.LayoutParams(1,dp(h)));}
 LinearLayout card(LinearLayout parent,String title,String note){LinearLayout c=column();c.setPadding(dp(20),dp(18),dp(20),dp(18));c.setBackground(shape(CARD,24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(14);parent.addView(c,lp);c.addView(text(title,17,FG));if(note!=null){gap(c,5);TextView t=text(note,12,MUTED);t.setLineSpacing(dp(3),1);c.addView(t);}gap(c,14);return c;}
 void build(){
  LinearLayout root=column();root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout body=column();body.setPadding(dp(22),dp(22),dp(22),dp(18));scroll.addView(body);
  TextView eyebrow=text("小米手表 S4 · 人像表盘",12,ACCENT);eyebrow.setLetterSpacing(.08f);body.addView(eyebrow);gap(body,7);TextView title=text(getString(R.string.app_name),30,FG);title.setTypeface(null,android.graphics.Typeface.BOLD);body.addView(title);gap(body,5);body.addView(text("一张喜欢的照片，戴在手腕上。",14,MUTED));gap(body,20);
  preview=new WatchPreview(this,engine);int previewSize=Math.min(dp(316),getResources().getDisplayMetrics().widthPixels-dp(56));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(previewSize,previewSize);pp.gravity=Gravity.CENTER_HORIZONTAL;body.addView(preview,pp);gap(body,11);TextView hint=text("预览为示例数据 · 手表上随时间和数据更新",11,MUTED);hint.setGravity(Gravity.CENTER);body.addView(hint);
  LinearLayout photo=card(body,"01  选择图片","拖动预览调整位置，双指缩放，让人物的脸居中。圆角与当前表盘保持一致。");
  LinearLayout row=new LinearLayout(this);chooseButton=button("选择图片",true);Button reset=button("恢复取景",false);LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,dp(48),1);row.addView(chooseButton,half);LinearLayout.LayoutParams other=new LinearLayout.LayoutParams(0,dp(48),1);other.leftMargin=dp(10);row.addView(reset,other);photo.addView(row);
  chooseButton.setOnClickListener(v->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(pick,PICK_PHOTO);}catch(ActivityNotFoundException e){message("手机没有可用的图片选择器");}});
  reset.setOnClickListener(v->{if(preview.photo!=null){preview.crop.reset();preview.crop.clamp(preview.photo);preview.invalidate();zoom.setProgress(0);save();}else message("选择图片后，可以拖动和缩放取景");});
  gap(photo,12);LinearLayout zr=new LinearLayout(this);zr.setGravity(Gravity.CENTER_VERTICAL);zr.addView(text("缩放",12,MUTED));zoom=new SeekBar(this);zoom.setMax(300);zr.addView(zoom,new LinearLayout.LayoutParams(0,dp(40),1));photo.addView(zr);zoom.setEnabled(false);zoom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int value,boolean user){if(user&&preview.photo!=null){preview.crop.zoom=1+value/100f;preview.crop.clamp(preview.photo);preview.invalidate();save();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){save();}});
  TextView useDefault=text("恢复若叶睦默认图片",12,ACCENT);useDefault.setPadding(0,dp(10),0,dp(4));photo.addView(useDefault);useDefault.setOnClickListener(v->{if(busy)return;photoFile().delete();preview.setPhoto(null);zoom.setEnabled(false);zoom.setProgress(0);imageColors.removeAllViews();save();message("已恢复若叶睦默认图片");});
  LinearLayout colors=card(body,"02  电量区域颜色","默认使用图片中的墨绿色；浅色背景会自动搭配深色图标和数字。");LinearLayout cr=new LinearLayout(this);cr.setGravity(Gravity.CENTER_VERTICAL);colorLabel=text("#2E5B58",16,FG);cr.addView(colorLabel,new LinearLayout.LayoutParams(0,-2,1));Button custom=button("自定义",false);cr.addView(custom,new LinearLayout.LayoutParams(dp(104),dp(44)));colors.addView(cr);custom.setOnClickListener(v->ColorPicker.show(this,preview.color,this::setColor));gap(colors,14);
  LinearLayout swatches=new LinearLayout(this);int[] palette={WatchfaceEngine.GREEN,0xff23433a,0xff748b75,0xff526f82,0xffb98777,0xff93859c};for(int c:palette)addSwatch(swatches,c);colors.addView(swatches);gap(colors,12);imageColors=new LinearLayout(this);colors.addView(imageColors);TextView extract=text("从当前图片提取配色",12,ACCENT);extract.setPadding(0,dp(6),0,dp(6));colors.addView(extract);extract.setOnClickListener(v->extractColors());
  LinearLayout details=card(body,"03  保存表盘","导出为小米手表 S4 表盘文件，再通过你平时使用的表盘安装工具导入。");LinearLayout nr=new LinearLayout(this);nr.setGravity(Gravity.CENTER_VERTICAL);nr.addView(text("表盘名称",13,MUTED),new LinearLayout.LayoutParams(0,-2,1));Button name=button("修改名称",false);name.setOnClickListener(v->editName());nr.addView(name,new LinearLayout.LayoutParams(dp(104),dp(42)));details.addView(nr);status=text(faceName+" · 466 × 466",12,FG);gap(details,8);details.addView(status);TextView savePreview=text("保存当前预览图片",12,ACCENT);savePreview.setPadding(0,dp(14),0,dp(4));details.addView(savePreview);savePreview.setOnClickListener(v->savePreview());
  LinearLayout bottom=column();bottom.setPadding(dp(22),dp(12),dp(22),dp(6));exportButton=button("导出表盘文件",true);bottom.addView(exportButton,new LinearLayout.LayoutParams(-1,dp(54)));TextView about=text("关于 · 检查更新",12,MUTED);about.setGravity(Gravity.CENTER);about.setContentDescription("关于画廊表盘制作器和检查更新");bottom.addView(about,new LinearLayout.LayoutParams(-1,dp(44)));about.setOnClickListener(v->startActivity(new Intent(this,AboutActivity.class)));root.addView(bottom);exportButton.setOnClickListener(v->prepareExport());setContentView(root);root.requestApplyInsets();preview.changed=()->{zoom.setProgress(Math.round((preview.crop.zoom-1)*100));save();};
 }
 void setColor(int color){preview.setColor(color);colorLabel.setText(String.format(Locale.ROOT,"#%06X",color&0xffffff));save();}
 void addSwatch(LinearLayout parent,int color){View swatch=new View(this);GradientDrawable bg=shape(color,50);bg.setStroke(dp(1),0xff6b8074);swatch.setBackground(bg);swatch.setContentDescription(String.format(Locale.ROOT,"使用颜色 #%06X",color&0xffffff));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(34),1);lp.rightMargin=dp(7);lp.leftMargin=dp(2);parent.addView(swatch,lp);swatch.setOnClickListener(v->setColor(color));}
 void restore(){int color=prefs.getInt("color",WatchfaceEngine.GREEN);float x=prefs.getFloat("x",.5f),y=prefs.getFloat("y",.5f),z=prefs.getFloat("zoom",1);preview.setColor(color);colorLabel.setText(String.format(Locale.ROOT,"#%06X",color&0xffffff));if(photoFile().exists())try{Bitmap p=BitmapFactory.decodeFile(photoFile().getAbsolutePath());if(p!=null){preview.setPhoto(p);preview.crop.x=x;preview.crop.y=y;preview.crop.zoom=z;preview.crop.clamp(p);zoom.setEnabled(true);zoom.setProgress(Math.round((preview.crop.zoom-1)*100));}}catch(Exception e){message("上次的图片未能加载，请重新选择");}}
 void save(){if(preview==null)return;prefs.edit().putInt("color",preview.color).putFloat("x",preview.crop.x).putFloat("y",preview.crop.y).putFloat("zoom",preview.crop.zoom).putString("name",faceName).apply();}
 @Override protected void onPause(){super.onPause();save();}
 void setBusy(boolean value,String label){busy=value;exportButton.setEnabled(!value);chooseButton.setEnabled(!value);exportButton.setText(value?label:"导出表盘文件");}
 void message(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 boolean alive(){return !isFinishing()&&!isDestroyed();}
 void error(String label,Throwable error){if(alive()){setBusy(false,"");new AlertDialog.Builder(this).setTitle(label).setMessage(error instanceof OutOfMemoryError?"图片过大，请换一张较小的图片后再试。":error.getMessage()==null?"请重试。":error.getMessage()).setPositiveButton("知道了",null).show();}}
 void editName(){EditText input=new EditText(this);input.setSingleLine();input.setText(faceName);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(18)});LinearLayout wrap=column();wrap.setPadding(dp(24),dp(4),dp(24),0);wrap.addView(input);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("表盘名称").setView(wrap).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String name=input.getText().toString().trim();if(name.isEmpty()||name.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>63){input.setError("请输入 1～18 个字");return;}faceName=name;status.setText(faceName+" · 466 × 466");save();dialog.dismiss();}));dialog.show();}
 void extractColors(){if(busy)return;Bitmap source=preview.photo==null?engine.singles.get(1):preview.photo;Bitmap small=Bitmap.createScaledBitmap(source,80,80,true);int[] p=new int[6400];small.getPixels(p,0,80,0,0,80,80);HashMap<Integer,Integer> counts=new HashMap<>();for(int c:p){int key=(Color.red(c)>>4)<<8|(Color.green(c)>>4)<<4|(Color.blue(c)>>4);float[] hsv=new float[3];Color.colorToHSV(c,hsv);if(hsv[2]>.12&&hsv[2]<.96)counts.merge(key,1,Integer::sum);}ArrayList<Integer> keys=new ArrayList<>(counts.keySet());keys.sort((a,b)->Integer.compare(counts.get(b),counts.get(a)));ArrayList<Integer> selected=new ArrayList<>();for(int key:keys){int c=Color.rgb((key>>8&15)*16+8,(key>>4&15)*16+8,(key&15)*16+8);boolean distinct=true;for(int old:selected)if(Math.abs(Color.red(c)-Color.red(old))+Math.abs(Color.green(c)-Color.green(old))+Math.abs(Color.blue(c)-Color.blue(old))<80)distinct=false;if(distinct)selected.add(c);if(selected.size()==5)break;}imageColors.removeAllViews();if(selected.isEmpty())message("这张图片的配色较单一，可以使用自定义颜色");else for(int c:selected)addSwatch(imageColors,c);if(small!=source)small.recycle();}
 void loadPhoto(Uri uri){if(busy)return;setBusy(true,"正在载入图片…");worker.execute(()->{try{ImageDecoder.Source source;try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("无法读取所选图片");source=ImageDecoder.createSource(java.nio.ByteBuffer.wrap(WatchfaceEngine.read(input)));}Bitmap image=ImageDecoder.decodeBitmap(source,(decoder,info,s)->{int w=info.getSize().getWidth(),h=info.getSize().getHeight();float ratio=Math.min(1,2048f/Math.max(w,h));decoder.setTargetSize(Math.max(1,Math.round(w*ratio)),Math.max(1,Math.round(h*ratio)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});File temp=new File(getFilesDir(),"photo.tmp");try(FileOutputStream out=new FileOutputStream(temp)){if(!image.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("图片保存失败");}java.nio.file.Files.move(temp.toPath(),photoFile().toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);prefs.edit().putFloat("x",.5f).putFloat("y",.5f).putFloat("zoom",1).commit();runOnUiThread(()->{if(!alive())return;preview.setPhoto(image);zoom.setEnabled(true);zoom.setProgress(0);imageColors.removeAllViews();setBusy(false,"");save();});}catch(Exception|OutOfMemoryError e){runOnUiThread(()->error("图片未能打开",e));}});}
 void prepareExport(){if(busy)return;save();setBusy(true,"正在制作表盘…");Bitmap image=preview.photo;Crop crop=new Crop(preview.crop);int color=preview.color;String title=faceName;
  worker.execute(()->{try{byte[] bin=engine.export(image,crop,color,title);try(FileOutputStream out=new FileOutputStream(pendingFile())){out.write(bin);}runOnUiThread(()->{if(!alive())return;setBusy(false,"");Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,title.replaceAll("[\\\\/:*?\"<>|]","_")+"_S4.bin");try{startActivityForResult(save,SAVE_BIN);}catch(ActivityNotFoundException e){error("无法保存",new IOException("手机没有可用的文件选择器"));}});}catch(Exception|OutOfMemoryError e){runOnUiThread(()->error("表盘制作失败",e));}});
 }
 void savePreview(){if(busy)return;Bitmap bitmap=Bitmap.createBitmap(466,466,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Path circle=new Path();circle.addCircle(233,233,233,Path.Direction.CW);canvas.clipPath(circle);engine.background(canvas,preview.photo,preview.crop,preview.color,preview.bottom);engine.foreground(canvas,preview.color,WatchfaceEngine.sample("2560","80"));try(FileOutputStream out=new FileOutputStream(new File(getFilesDir(),"preview.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("image/png").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,faceName+"_预览.png"),SAVE_PREVIEW);}catch(Exception e){error("预览保存失败",e);}finally{bitmap.recycle();}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==PICK_PHOTO){loadPhoto(uri);return;}if(request!=SAVE_BIN&&request!=SAVE_PREVIEW)return;File file=request==SAVE_BIN?pendingFile():new File(getFilesDir(),"preview.png");setBusy(true,"正在保存…");worker.execute(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("目标位置不可写，请换一个文件夹");byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);runOnUiThread(()->{if(alive()){setBusy(false,"");message(request==SAVE_BIN?"表盘已保存，可在安装工具中导入":"预览图片已保存");}});}catch(Exception e){runOnUiThread(()->error("文件保存失败",e));}});}
 @Override protected void onDestroy(){super.onDestroy();worker.shutdown();}
}
